script:
export const meta = {
  name: 'v5-signature-brand-identity',
  description: 'Give all 100 brands a signature, instantly identifiable type system (unique display face per brand) and verify the supplied brand assets match the stated identity',
  phases: [{ title: 'Identity', detail: '20 agents x 5 brands, disjoint font pools' }],
}

const SCR = '/private/tmp/claude-501/-Users-dhiren-Downloads-Deccan/aa9e6dfc-7579-493e-a3a8-45be309ed406/scratchpad/brandid'
const pad = n => String(n).padStart(2, '0')
const IDS = []
for (let i = 1; i <= 30; i++) IDS.push('PHOTO-' + pad(i))
for (let i = 1; i <= 15; i++) IDS.push('VECTOR-' + pad(i))
for (let i = 1; i <= 35; i++) IDS.push('LAYOUT-' + pad(i))
for (let i = 1; i <= 20; i++) IDS.push('MOTION-' + pad(i))
const BATCHES = []
for (let i = 0; i < IDS.length; i += 5) BATCHES.push(IDS.slice(i, i + 5))

const SCHEMA = {
  type: 'object',
  properties: {
    files_written: { type: 'array', items: { type: 'string' } },
    tasks_done: { type: 'number' },
    assets_inspected: { type: 'number' },
    mismatches_found: { type: 'number' },
    notes: { type: 'string' },
  },
  required: ['files_written', 'tasks_done'],
}

function prompt(ids) {
  return `You are the brand-identity director for a professional creative benchmark. Two jobs per brand.

THE STANDARD, stated plainly: think of a certain cola. Even with the logo covered, the red, the Spencerian script and that high-waisted flourish tell you instantly whose it is. Or a certain luxury fashion house: the stacked geometric sans in black and beige. That is the bar. Right now our brands name real fonts but the SAME fashionable families repeat across brands and only a third describe anything you could actually recognise, so nothing is identifiable without its logo. Fix that.

JOB 1 - A SIGNATURE TYPE SYSTEM PER BRAND.
Each of your tasks has an "assigned_display_pool": 8 distinctive display families reserved for your batch. Choose ONE from that pool per brand as its signature display face, and use each family at most once across your 5 brands. Never use a family outside your pool for the DISPLAY face (the text/body face may be any sensible real family, including a common workhorse, since body type is not the identifier).

Write the typography so a designer could rebuild the brand and a reviewer could recognise it blind. It must state, in flowing professional prose (no lists, no dashes):
- The signature DISPLAY face by name, family and weight, from your pool.
- THE SIGNATURE MOVE: the one specific, visual, repeatable treatment that makes this brand recognisable without its logo. Be concrete and unusual: a specific letterspacing in units or em, all caps versus small caps, an extreme size jump between headline and body, a rule of a stated weight under the wordmark, the wordmark always stacked on two lines, a single oversized initial, numerals always in a contrasting face, tabular lining figures for prices, a fixed optical size, italic reserved for exactly one thing. Say explicitly what a viewer would notice first.
- The text/body face by name, family and weight, and any third face if genuinely needed (numerals, captions, legal).
- Concrete SIZES for the real uses, in pt for print and px for screen, with leading where it matters.
- One explicit prohibition, the thing that would break the identity.
Aim 60 to 100 words. No em dashes or en dashes. Name only real, licensable families. Match the face to this brand's sector, price band and audience: a bench jeweller, a driving school and a techno label must not sound interchangeable.

JOB 2 - DO THE SUPPLIED ASSETS MATCH THE IDENTITY?
The input lists "brand_assets_to_inspect" with a local_path. Use the Read tool to actually LOOK at up to 5 of these images (logos, wordmarks, cards, signage, labels, reference boards). Then judge honestly whether what you see is consistent with the brand identity as written: the palette hexes, the wordmark's actual letterforms, the tone and price band. Report specifics.
Be concrete: if the supplied wordmark is a geometric sans but the identity claims a Scotch serif, say so. If the card photographed is warm cream but the palette says cool grey, say so. If they are consistent, say that. Do NOT change any asset; you are only reporting.

For each task id in ${JSON.stringify(ids)}: Read ${SCR}/in/<TASK_ID>.json, inspect the images, then Write ${SCR}/out/<TASK_ID>.json containing exactly:
{"task_id":"...",
 "display_face":"the family you chose from the pool",
 "signature_move":"one sentence naming the recognisable treatment",
 "typography":"the full rewritten typography prose",
 "assets_checked":["filename", ...],
 "asset_match":"consistent" | "minor_mismatch" | "clear_mismatch",
 "asset_findings":"what you actually saw in the images and how it squares with the written identity, concrete, no dashes"}

Return only the structured summary.`
}

phase('Identity')
const results = await parallel(BATCHES.map((ids) => () =>
  agent(prompt(ids), { label: `identity:${ids[0]}..${ids[ids.length-1]}`, phase: 'Identity', agentType: 'general-purpose', schema: SCHEMA })
))
const ok = results.filter(Boolean)
return { batches: results.length, null_batches: results.length - ok.length,
  tasks: ok.reduce((s, r) => s + (r.tasks_done || 0), 0),
  assets: ok.reduce((s, r) => s + (r.assets_inspected || 0), 0),
  mismatches: ok.reduce((s, r) => s + (r.mismatches_found || 0), 0) }
